USE `sale`;

/*Table structure for table `cashaccount` */

DROP TABLE IF EXISTS `cashaccount`;

CREATE TABLE `cashaccount` (
  `cashaccountid` int NOT NULL AUTO_INCREMENT COMMENT '收银id',
  `cashierid` int DEFAULT NULL COMMENT '收银员id',
  `uid` int DEFAULT NULL COMMENT '顾客id',
  `settle_accountsid` int DEFAULT NULL COMMENT '扎帐id',
  `cashier_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '收银时间',
  `payment` tinyint DEFAULT NULL COMMENT '支付方式',
  `amount_money` decimal(18,3) DEFAULT NULL COMMENT '应收金额',
  `actual_money` decimal(18,3) DEFAULT NULL COMMENT '实收金额',
  `discount_money` decimal(18,3) DEFAULT NULL COMMENT '优惠金额',
  `sales_status` tinyint DEFAULT NULL COMMENT '销售状态(0正常 ,1已退货)',
  PRIMARY KEY (`cashaccountid`),
  KEY `cashierid` (`cashierid`),
  KEY `settle_accountsid` (`settle_accountsid`),
  CONSTRAINT `cashaccount_ibfk_1` FOREIGN KEY (`cashierid`) REFERENCES `cashier` (`cashierid`),
  CONSTRAINT `cashaccount_ibfk_2` FOREIGN KEY (`settle_accountsid`) REFERENCES `settle_accounts` (`settle_accountsid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Data for the table `cashaccount` */

/*Table structure for table `cashaccount_detail` */

DROP TABLE IF EXISTS `cashaccount_detail`;

CREATE TABLE `cashaccount_detail` (
  `cashaccountdetailid` int NOT NULL AUTO_INCREMENT COMMENT '收银明细id',
  `cashaccountid` int DEFAULT NULL COMMENT '收银id',
  `gid` int DEFAULT NULL COMMENT '货品id',
  `salesquantity` decimal(18,3) DEFAULT NULL COMMENT '销售数量',
  `retailprice` decimal(18,3) DEFAULT NULL COMMENT '零售价',
  `promotionalprice` decimal(18,3) DEFAULT NULL COMMENT '促销价',
  PRIMARY KEY (`cashaccountdetailid`),
  KEY `cashaccountid` (`cashaccountid`),
  KEY `gid` (`gid`),
  CONSTRAINT `cashaccount_detail_ibfk_1` FOREIGN KEY (`cashaccountid`) REFERENCES `cashaccount` (`cashaccountid`),
  CONSTRAINT `cashaccount_detail_ibfk_2` FOREIGN KEY (`gid`) REFERENCES `goods` (`gid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Data for the table `cashaccount_detail` */

/*Table structure for table `cashier` */

DROP TABLE IF EXISTS `cashier`;

CREATE TABLE `cashier` (
  `cashierid` int NOT NULL AUTO_INCREMENT,
  `cashier_Name` varchar(20) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `password` varchar(20) DEFAULT NULL,
  `roleid` int DEFAULT NULL,
  PRIMARY KEY (`cashierid`),
  KEY `cashier_role_roleid_fk` (`roleid`),
  CONSTRAINT `cashier_role_roleid_fk` FOREIGN KEY (`roleid`) REFERENCES `role` (`roleid`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

