/*Table structure for table `goods` */

DROP TABLE IF EXISTS `goods`;

CREATE TABLE `goods` (
  `gid` int NOT NULL AUTO_INCREMENT,
  `gname` varchar(20) DEFAULT NULL,
  `unit` varchar(20) DEFAULT NULL,
  `barcode` varchar(20) DEFAULT NULL,
  `qualityperiod` date DEFAULT NULL,
  `shelfid` int DEFAULT NULL,
  `retail_Price` decimal(10,2) DEFAULT NULL,
  `promotional_Price` decimal(10,2) DEFAULT NULL,
  `abbreviations` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`gid`),
  KEY `shelfid` (`shelfid`),
  CONSTRAINT `goods_ibfk_1` FOREIGN KEY (`shelfid`) REFERENCES `shelf` (`shelfid`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb3;

