/*Table structure for table `role` */

DROP TABLE IF EXISTS `role`;

CREATE TABLE `role` (
  `roleid` int NOT NULL AUTO_INCREMENT,
  `rolename` varchar(20) DEFAULT NULL,
  `rolelist` json DEFAULT NULL,
  PRIMARY KEY (`roleid`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Data for the table `role` */

insert  into `role`(`roleid`,`rolename`,`rolelist`) values (1,'管理员','[\"goods\", \"shelf\", \"user\", \"cashier\", \"cashaccount\", \"cashaccount_detail\", \"role\", \"settle_accounts\"]'),(2,'普通用户','[\"goods\", \"cashaccount\", \"cashaccount_detail\", \"settle_accounts\"]');

/*Table structure for table `settle_accounts` */

DROP TABLE IF EXISTS `settle_accounts`;

CREATE TABLE `settle_accounts` (
  `settle_accountsid` int NOT NULL AUTO_INCREMENT COMMENT '扎帐id',
  `cashierid` int DEFAULT NULL COMMENT '收银员id',
  `settle_accounts_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '扎帐时间',
  `amount_money` decimal(18,3) DEFAULT NULL COMMENT '应收金额',
  `actual_money` decimal(18,3) DEFAULT NULL COMMENT '实收金额',
  `errorReason` varchar(100) NOT NULL COMMENT '差错原因',
  PRIMARY KEY (`settle_accountsid`),
  KEY `cashierid` (`cashierid`),
  CONSTRAINT `settle_accounts_ibfk_1` FOREIGN KEY (`cashierid`) REFERENCES `cashier` (`cashierid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Data for the table `settle_accounts` */

/*Table structure for table `shelf` */

DROP TABLE IF EXISTS `shelf`;

CREATE TABLE `shelf` (
  `shelfid` int NOT NULL AUTO_INCREMENT,
  `shelfcode` varchar(20) DEFAULT NULL,
  `zone` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`shelfid`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb3;

/*Data for the table `shelf` */

insert  into `shelf`(`shelfid`,`shelfcode`,`zone`) values (1,'SHELF001','A区'),(2,'SHELF002','B区'),(3,'SHELF003','C区'),(4,'SHELF004','D区'),(5,'SHELF005','E区');

/*Table structure for table `stock` */

DROP TABLE IF EXISTS `stock`;

CREATE TABLE `stock` (
  `stockid` int NOT NULL AUTO_INCREMENT COMMENT '库存id',
  `gid` int DEFAULT NULL COMMENT '货品id',
  `quantity` decimal(18,3) DEFAULT NULL COMMENT '(当前)库存数量',
  `yesterday_quantity` decimal(18,3) DEFAULT NULL COMMENT '昨日库存(用于日清),系统自动维护',
  `month_quantity` decimal(18,3) DEFAULT NULL COMMENT '月初库存(用于月结),系统自动维护',
  PRIMARY KEY (`stockid`),
  KEY `gid` (`gid`),
  CONSTRAINT `stock_ibfk_1` FOREIGN KEY (`gid`) REFERENCES `goods` (`gid`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb3;

/*Data for the table `stock` */

insert  into `stock`(`stockid`,`gid`,`quantity`,`yesterday_quantity`,`month_quantity`) values (1,8,'23.000',NULL,NULL),(2,9,'12.000',NULL,NULL),(3,10,'0.000',NULL,NULL),(4,11,'0.000',NULL,NULL),(5,12,'0.000',NULL,NULL),(6,13,'20.000',NULL,NULL);

/*Table structure for table `user` */

DROP TABLE IF EXISTS `user`;

CREATE TABLE `user` (
  `uid` int NOT NULL AUTO_INCREMENT,
  `uname` varchar(20) DEFAULT NULL,
  `sex` varchar(20) DEFAULT NULL,
  `card_number` varchar(20) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `card_balance` decimal(10,2) DEFAULT NULL,
  `points` int DEFAULT NULL,
  `last_purchase_date` date DEFAULT NULL,
  `address` varchar(100) DEFAULT NULL,
  `membershiplevel` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`uid`)
) ENGINE=InnoDB AUTO_INCREMENT=10000 DEFAULT CHARSET=utf8mb3;

/*Data for the table `user` */

/* Trigger structure for table `goods` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `add_stock` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'%' */ /*!50003 TRIGGER `add_stock` AFTER INSERT ON `goods` FOR EACH ROW BEGIN
    INSERT INTO stock (gid, quantity) VALUES (NEW.gid, 0);
END */$$


DELIMITER ;

/*Table structure for table `v_goods_stock` */

DROP TABLE IF EXISTS `v_goods_stock`;

/*!50001 DROP VIEW IF EXISTS `v_goods_stock` */;
/*!50001 DROP TABLE IF EXISTS `v_goods_stock` */;

/*!50001 CREATE TABLE  `v_goods_stock`(
 `gid` int ,
 `gname` varchar(20) ,
 `unit` varchar(20) ,
 `barcode` varchar(20) ,
 `qualityperiod` date ,
 `shelfcode` varchar(20) ,
 `retail_Price` decimal(10,2) ,
 `promotional_Price` decimal(10,2) ,
 `quantity` decimal(18,3) 
)*/;

/*View structure for view v_goods_stock */

/*!50001 DROP TABLE IF EXISTS `v_goods_stock` */;
/*!50001 DROP VIEW IF EXISTS `v_goods_stock` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `v_goods_stock` AS select `goods`.`gid` AS `gid`,`goods`.`gname` AS `gname`,`goods`.`unit` AS `unit`,`goods`.`barcode` AS `barcode`,`goods`.`qualityperiod` AS `qualityperiod`,`shelf`.`shelfcode` AS `shelfcode`,`goods`.`retail_Price` AS `retail_Price`,`goods`.`promotional_Price` AS `promotional_Price`,`stock`.`quantity` AS `quantity` from ((`goods` join `stock`) join `shelf`) where ((`goods`.`gid` = `stock`.`gid`) and (`goods`.`shelfid` = `shelf`.`shelfid`)) */;

